import { createCanvas, GlobalFonts, loadImage } from '@napi-rs/canvas'

const _fc = new Set()
const _fb = 'https://raw.githubusercontent.com/Reyz2902/font2/main/'
async function lf(file, alias) {
    if (_fc.has(alias)) return
    const r = await fetch(_fb + encodeURIComponent(file))
    if (!r.ok) throw new Error('Font gagal: ' + file)
    GlobalFonts.register(Buffer.from(await r.arrayBuffer()), alias)
    _fc.add(alias)
}

function rrp(ctx, x, y, w, h, r) {
    ctx.beginPath()
    ctx.moveTo(x + r, y)
    ctx.lineTo(x + w - r, y)
    ctx.quadraticCurveTo(x + w, y, x + w, y + r)
    ctx.lineTo(x + w, y + h - r)
    ctx.quadraticCurveTo(x + w, y + h, x + w - r, y + h)
    ctx.lineTo(x + r, y + h)
    ctx.quadraticCurveTo(x, y + h, x, y + h - r)
    ctx.lineTo(x, y + r)
    ctx.quadraticCurveTo(x, y, x + r, y)
    ctx.closePath()
}

function petal(ctx, cx, cy, r, angle, color, alpha) {
    ctx.save()
    ctx.globalAlpha = alpha
    ctx.translate(cx, cy)
    ctx.rotate(angle)
    ctx.beginPath()
    ctx.moveTo(0, 0)
    ctx.bezierCurveTo(-r * 0.5, -r * 0.8, -r * 0.3, -r * 1.5, 0, -r * 1.6)
    ctx.bezierCurveTo(r * 0.3, -r * 1.5, r * 0.5, -r * 0.8, 0, 0)
    ctx.fillStyle = color
    ctx.fill()
    ctx.restore()
}

function sakura(ctx, cx, cy, r, color, alpha = 1) {
    for (let i = 0; i < 5; i++) petal(ctx, cx, cy, r, (Math.PI * 2 / 5) * i, color, alpha)
    ctx.save()
    ctx.globalAlpha = alpha
    ctx.beginPath()
    ctx.arc(cx, cy, r * 0.3, 0, Math.PI * 2)
    ctx.fillStyle = '#fff8f0'
    ctx.fill()
    ctx.restore()
}

function fadeLine(ctx, y, W, color) {
    const g = ctx.createLinearGradient(30, 0, W - 30, 0)
    g.addColorStop(0, 'transparent')
    g.addColorStop(0.12, color)
    g.addColorStop(0.88, color)
    g.addColorStop(1, 'transparent')
    ctx.strokeStyle = g
    ctx.lineWidth = 1
    ctx.beginPath()
    ctx.moveTo(30, y)
    ctx.lineTo(W - 30, y)
    ctx.stroke()
}

function cornerL(ctx, x, y, w, h, size, color) {
    ctx.strokeStyle = color
    ctx.lineWidth = 1.8
    ;[[x, y, 1, 1], [x + w, y, -1, 1], [x, y + h, 1, -1], [x + w, y + h, -1, -1]]
        .forEach(([cx, cy, dx, dy]) => {
            ctx.beginPath()
            ctx.moveTo(cx + dx * size, cy)
            ctx.lineTo(cx, cy)
            ctx.lineTo(cx, cy + dy * size)
            ctx.stroke()
        })
}

const TIERS = [
    { min: 0,  label: 'Newbie',  status: 'Dormant',  color: '#a8d8a8',
      desc: ['Level rendah banget.', 'Mode blend masih aktif.'] },
    { min: 20, label: 'Rising',  status: 'Warming',  color: '#90caf9',
      desc: ['Early bloomer detected.', 'Aura fem mulai terbaca.'] },
    { min: 40, label: 'Solid',   status: 'Growing',  color: '#f4a261',
      desc: ['Cukup solid!', 'Ekspresi fem makin berani.'] },
    { min: 60, label: 'High',    status: 'Active',   color: '#f48fb1',
      desc: ['Sisi fem mulai keliatan.', 'Filter telinga kucing favorit.'] },
    { min: 75, label: 'Elite',   status: 'Active',   color: '#e07098',
      desc: ['Tingkat femboy sangat tinggi.', 'Aura fem memancar ke seluruh grup.'] },
    { min: 90, label: 'Legend',  status: 'Overflow', color: '#b08ad0',
      desc: ['LEGENDARY FEMBOY.', 'Server jadi pink semua.'] },
]

function getTier(pct) {
    let t = TIERS[0]
    for (const tier of TIERS) { if (pct >= tier.min) t = tier }
    return t
}

export async function generateCard(nama, pct, avatarBuf, botname = 'Bot', website = '') {
    await lf('SFPRODISPLAYBOLD.OTF', 'SFBold')
    await lf('SFPRODISPLAYMEDIUM.OTF', 'SFMedium')
    await lf('SFPRODISPLAYREGULAR.OTF', 'SFRegular')
    await lf('NotoColorEmoji-Regular.ttf', 'Emoji')

    const W = 720, H = 460
    const canvas = createCanvas(W, H)
    const ctx = canvas.getContext('2d')
    const tier = getTier(pct)
    const tc = tier.color

    const bgG = ctx.createLinearGradient(0, 0, W, H)
    bgG.addColorStop(0, '#fdf8f0')
    bgG.addColorStop(0.5, '#fef9f2')
    bgG.addColorStop(1, '#faf3e8')
    ctx.fillStyle = bgG
    ctx.fillRect(0, 0, W, H)

    for (let i = 0; i < 700; i++) {
        ctx.fillStyle = `rgba(180,140,100,${Math.random() * 0.025 + 0.005})`
        ctx.beginPath()
        ctx.arc(Math.random() * W, Math.random() * H, Math.random() * 0.9, 0, Math.PI * 2)
        ctx.fill()
    }

    const vign = ctx.createRadialGradient(W / 2, H / 2, H * 0.18, W / 2, H / 2, W * 0.78)
    vign.addColorStop(0, 'transparent')
    vign.addColorStop(1, 'rgba(140,90,40,0.14)')
    ctx.fillStyle = vign
    ctx.fillRect(0, 0, W, H)

    const warmBlob = ctx.createRadialGradient(W * 0.12, H * 0.18, 0, W * 0.12, H * 0.18, 220)
    warmBlob.addColorStop(0, tc + '18')
    warmBlob.addColorStop(1, 'transparent')
    ctx.fillStyle = warmBlob
    ctx.fillRect(0, 0, W, H)

    const M = 20
    rrp(ctx, M, M, W - M * 2, H - M * 2, 16)
    ctx.strokeStyle = '#c9956e'
    ctx.lineWidth = 2
    ctx.stroke()
    rrp(ctx, M + 6, M + 6, W - M * 2 - 12, H - M * 2 - 12, 12)
    ctx.strokeStyle = 'rgba(201,149,110,0.25)'
    ctx.lineWidth = 1
    ctx.stroke()
    cornerL(ctx, M + 4, M + 4, W - M * 2 - 8, H - M * 2 - 8, 28, '#c9956e')

    const sp = '#f8a4c0', sl = '#fcc8d8', sd = '#e87098'
    sakura(ctx, 46, 46, 32, sl, 0.20)
    sakura(ctx, W - 50, 38, 25, sp, 0.16)
    sakura(ctx, 38, H - 46, 28, sp, 0.18)
    sakura(ctx, W - 44, H - 50, 30, sl, 0.15)
    sakura(ctx, W * 0.5, 30, 16, sd, 0.10)
    ;[
        [W * 0.82, H * 0.08, 10, 0.3, sp],
        [W * 0.12, H * 0.25, 8, 0.8, sl],
        [W * 0.92, H * 0.52, 9, 1.1, sp],
        [W * 0.08, H * 0.74, 9, 0.2, sd],
        [W * 0.76, H * 0.90, 8, 1.5, sl],
        [W * 0.42, H * 0.96, 7, 0.6, sp],
        [W * 0.95, H * 0.28, 7, 1.8, sd],
    ].forEach(([px, py, pr, pa, pc]) => petal(ctx, px, py, pr, pa, pc, 0.48))

    const AV_R = 72
    const AV_CX = M + 28 + AV_R
    const AV_CY = H / 2

    const ringG = ctx.createLinearGradient(AV_CX - AV_R, AV_CY - AV_R, AV_CX + AV_R, AV_CY + AV_R)
    ringG.addColorStop(0, tc)
    ringG.addColorStop(0.5, tc + 'aa')
    ringG.addColorStop(1, tc)
    ctx.beginPath()
    ctx.arc(AV_CX, AV_CY, AV_R + 6, 0, Math.PI * 2)
    ctx.strokeStyle = ringG
    ctx.lineWidth = 3
    ctx.stroke()

    ctx.save()
    ctx.setLineDash([4, 5])
    ctx.beginPath()
    ctx.arc(AV_CX, AV_CY, AV_R + 12, 0, Math.PI * 2)
    ctx.strokeStyle = tc + '55'
    ctx.lineWidth = 1.2
    ctx.stroke()
    ctx.setLineDash([])
    ctx.restore()

    if (avatarBuf) {
        try {
            const img = await loadImage(avatarBuf)
            ctx.save()
            ctx.beginPath()
            ctx.arc(AV_CX, AV_CY, AV_R, 0, Math.PI * 2)
            ctx.clip()
            ctx.drawImage(img, AV_CX - AV_R, AV_CY - AV_R, AV_R * 2, AV_R * 2)
            ctx.restore()
        } catch {
            drawDefaultAvatar(ctx, AV_CX, AV_CY, AV_R)
        }
    } else {
        drawDefaultAvatar(ctx, AV_CX, AV_CY, AV_R)
    }

    const tierBadgeW = 76, tierBadgeH = 22
    const tbx = AV_CX - tierBadgeW / 2
    const tby = AV_CY + AV_R + 14
    rrp(ctx, tbx, tby, tierBadgeW, tierBadgeH, 11)
    ctx.fillStyle = tc + 'dd'
    ctx.fill()
    ctx.font = 'bold 10px SFBold'
    ctx.fillStyle = '#fff8f0'
    ctx.textAlign = 'center'
    ctx.fillText(tier.label.toUpperCase(), AV_CX, tby + 15)

    const TX = AV_CX + AV_R + 36
    const TW = W - TX - M - 14

    ctx.font = '9px SFBold'
    ctx.fillStyle = '#b07850'
    ctx.textAlign = 'left'
    ctx.fillText('✦  FEMBOY CHECKER  ✦', TX, H / 2 - 138)

    const displayName = nama.length > 20 ? nama.slice(0, 20) + '…' : nama
    ctx.font = `bold 30px SFBold`
    ctx.fillStyle = '#4a1e0a'
    ctx.shadowColor = 'rgba(201,149,110,0.28)'
    ctx.shadowBlur = 12
    ctx.textAlign = 'left'
    ctx.fillText(displayName, TX, H / 2 - 112)
    ctx.shadowBlur = 0

    ctx.font = '11px SFMedium'
    ctx.fillStyle = '#9b6a43'
    ctx.fillText(tier.status + '  ·  ' + botname, TX, H / 2 - 94)

    fadeLine(ctx, H / 2 - 82, W, 'rgba(201,149,110,0.3)')

    const bigLabel = pct === 69 ? 'Nice 👀' : pct === 100 ? '100% 💯' : `${pct}%`
    ctx.font = `bold 64px SFBold`
    ctx.fillStyle = tc
    ctx.shadowColor = tc + '66'
    ctx.shadowBlur = 22
    ctx.textAlign = 'left'
    ctx.fillText(bigLabel, TX, H / 2 - 14)
    ctx.shadowBlur = 0

    ctx.font = '10px SFMedium'
    ctx.fillStyle = '#9b6a43'
    ctx.fillText('fem energy level', TX, H / 2 + 6)

    const barX = TX, barY = H / 2 + 18, barW = TW, barH = 12
    rrp(ctx, barX, barY, barW, barH, 6)
    ctx.fillStyle = 'rgba(201,149,110,0.15)'
    ctx.fill()
    ctx.strokeStyle = 'rgba(201,149,110,0.28)'
    ctx.lineWidth = 1
    ctx.stroke()

    const fillW = Math.max(12, (pct / 100) * barW)
    const fG = ctx.createLinearGradient(barX, 0, barX + fillW, 0)
    fG.addColorStop(0, tc + 'bb')
    fG.addColorStop(1, tc)
    rrp(ctx, barX, barY, fillW, barH, 6)
    ctx.fillStyle = fG
    ctx.fill()

    for (let i = 0; i < 10; i++) {
        ctx.beginPath()
        ctx.arc(barX + i * 7, barY + barH + 10, 2.2, 0, Math.PI * 2)
        ctx.fillStyle = i < Math.round(pct / 10) ? tc : 'rgba(201,149,110,0.18)'
        ctx.fill()
    }

    fadeLine(ctx, H / 2 + 52, W, 'rgba(201,149,110,0.3)')

    ctx.font = '12px SFMedium'
    ctx.fillStyle = '#7a3e1a'
    ctx.textAlign = 'left'
    tier.desc.forEach((line, i) => ctx.fillText(line, TX, H / 2 + 72 + i * 20))

    const statY = H / 2 + 118
    const statW = (TW - 16) / 3
    ;[
        { label: 'TIER',   val: tier.label },
        { label: 'LEVEL',  val: pct + '%' },
        { label: 'STATUS', val: tier.status },
    ].forEach(({ label, val }, i) => {
        const sx = TX + i * (statW + 8)
        rrp(ctx, sx, statY, statW, 52, 10)
        ctx.fillStyle = 'rgba(201,149,110,0.07)'
        ctx.fill()
        ctx.strokeStyle = 'rgba(201,149,110,0.2)'
        ctx.lineWidth = 1
        ctx.stroke()
        rrp(ctx, sx, statY, statW, 3, 2)
        ctx.fillStyle = tc + 'cc'
        ctx.fill()
        ctx.font = '8px SFBold'
        ctx.fillStyle = '#9b6a43'
        ctx.textAlign = 'center'
        ctx.fillText(label, sx + statW / 2, statY + 18)
        ctx.font = 'bold 15px SFBold'
        ctx.fillStyle = '#3a1808'
        ctx.fillText(val, sx + statW / 2, statY + 38)
    })

    fadeLine(ctx, H - 36, W, 'rgba(201,149,110,0.28)')
    ctx.font = '9px SFRegular'
    ctx.fillStyle = 'rgba(154,100,60,0.5)'
    ctx.textAlign = 'center'
    ctx.fillText(`${botname}  ·  ${website}`, W / 2, H - 20)

    return canvas.toBuffer('image/jpeg', { quality: 96 })
}

function drawDefaultAvatar(ctx, cx, cy, r) {
    ctx.save()
    ctx.beginPath()
    ctx.arc(cx, cy, r, 0, Math.PI * 2)
    const aG = ctx.createRadialGradient(cx - 20, cy - 20, 10, cx, cy, r)
    aG.addColorStop(0, '#fde8f0')
    aG.addColorStop(1, '#f4b8cc')
    ctx.fillStyle = aG
    ctx.fill()
    ctx.restore()
    ctx.font = `56px Emoji`
    ctx.textAlign = 'center'
    ctx.fillText('🎀', cx, cy + 20)
}